package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SenderEmailVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property sender email of smtp outbound config ")
  void test_sender_email_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SenderEmailVO.tryFrom(null));
    Assertions.assertEquals("one", SenderEmailVO.from("one").getSenderEmail());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SenderEmailVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SenderEmailVO.from("one").toString());
  }
}
